      } },
    }])
    assert.deepEqual(result.timeouts, result.requests.map(() => timeout ? Number(timeout) : 30000))
    assert.deepEqual(result.requests.slice(-4), restorations(bodies))
    assert.deepEqual(result.events.slice(4), [
